// =============================================================================
// Quiz Preview — Live shopper simulation with desktop/mobile toggle
// =============================================================================

import { useState, useCallback } from "react";
import { data, type HeadersFunction, type LoaderFunctionArgs } from "react-router";
import { useLoaderData } from "react-router";
import {
  Page,
  Card,
  Button,
  ButtonGroup,
  InlineStack,
  BlockStack,
  Text,
  Badge,
  Box,
  Divider,
  SkeletonPage,
  SkeletonBodyText,
} from "@shopify/polaris";
import {
  DesktopIcon,
  MobileIcon,
  RefreshIcon,
} from "@shopify/polaris-icons";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import db from "../db.server";

// =============================================================================
// TYPES
// =============================================================================

interface AnswerOption {
  id: string;
  text: string;
  imageUrl: string;
  score: number;
  productTags: string[];
  nextQuestionId: string;
  position: number;
}

interface QuestionSettings {
  allowMultiple?: boolean;
  min?: number;
  max?: number;
  step?: number;
  unit?: string;
  minLabel?: string;
  maxLabel?: string;
  placeholder?: string;
  maxLength?: number;
  consentText?: string;
  skipLinkText?: string;
  maxRating?: number;
  ratingStyle?: string;
}

interface Question {
  id: string;
  title: string;
  description: string;
  imageUrl: string;
  type: string;
  required: boolean;
  position: number;
  settings: QuestionSettings;
  answers: AnswerOption[];
}

interface DesignSettings {
  primaryColor: string;
  buttonTextColor: string;
  buttonText: string;
  fontFamily: string;
  borderRadius: string;
  showProgressBar: boolean;
  progressBarStyle: string;
  showQuestionCount: boolean;
  resultsHeading: string;
}

interface QuizSettings {
  requireEmail: boolean;
  emailConsentText: string;
  showProgressBar: boolean;
}

interface ResultPageData {
  id: string;
  title: string;
  description: string | null;
  position: number;
}

interface LoaderQuiz {
  id: string;
  title: string;
  description: string;
  slug: string;
  status: string;
  type: string;
}

interface LoaderData {
  quiz: LoaderQuiz;
  questions: Question[];
  designSettings: DesignSettings;
  quizSettings: QuizSettings;
  resultPages: ResultPageData[];
}

type DeviceMode = "desktop" | "mobile";
type PreviewStep = "welcome" | "question" | "results";

// =============================================================================
// HELPERS
// =============================================================================

function parseSafe<T>(str: string, fallback: T): T {
  try {
    return JSON.parse(str) as T;
  } catch {
    return fallback;
  }
}

// =============================================================================
// LOADER
// =============================================================================

export const loader = async ({ request, params }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const quizId = params.id;

  if (!quizId) {
    throw data({ error: "Missing quiz ID" }, { status: 400 });
  }

  try {
    const quiz = await db.quiz.findFirst({
      where: { id: quizId, shop: session.shop },
      include: {
        questions: {
          include: { answers: { orderBy: { position: "asc" } } },
          orderBy: { position: "asc" },
        },
        resultPages: { orderBy: { position: "asc" } },
      },
    });

    if (!quiz) {
      throw data({ error: "Quiz not found" }, { status: 404 });
    }

    const stylingObj = parseSafe<{
      primaryColor?: string;
      buttonTextColor?: string;
      buttonText?: string;
      fontFamily?: string;
      borderRadius?: string;
      showProgressBar?: boolean;
      progressBarStyle?: string;
      showQuestionCount?: boolean;
      resultsHeading?: string;
    }>(quiz.styling, {});

    const settingsObj = parseSafe<{
      requireEmail?: boolean;
      emailConsentText?: string;
      showProgressBar?: boolean;
    }>(quiz.settings, {});

    const designSettings: DesignSettings = {
      primaryColor: stylingObj.primaryColor ?? "#5C6AC4",
      buttonTextColor: stylingObj.buttonTextColor ?? "#FFFFFF",
      buttonText: stylingObj.buttonText ?? "Next",
      fontFamily: stylingObj.fontFamily ?? "system",
      borderRadius: stylingObj.borderRadius ?? "8",
      showProgressBar: stylingObj.showProgressBar ?? true,
      progressBarStyle: stylingObj.progressBarStyle ?? "bar",
      showQuestionCount: stylingObj.showQuestionCount ?? false,
      resultsHeading: stylingObj.resultsHeading ?? "Your Results",
    };

    const quizSettings: QuizSettings = {
      requireEmail: settingsObj.requireEmail ?? false,
      emailConsentText:
        settingsObj.emailConsentText ?? "I agree to receive marketing emails.",
      showProgressBar: settingsObj.showProgressBar ?? true,
    };

    const questions: Question[] = quiz.questions.map((q) => ({
      id: q.id,
      title: q.title,
      description: q.description ?? "",
      imageUrl: q.imageUrl ?? "",
      type: q.type,
      required: q.required,
      position: q.position,
      settings: parseSafe<QuestionSettings>(q.settings, {}),
      answers: q.answers.map((a) => ({
        id: a.id,
        text: a.text,
        imageUrl: a.imageUrl ?? "",
        score: a.score,
        productTags: parseSafe<string[]>(a.productTags, []),
        nextQuestionId: a.nextQuestionId ?? "",
        position: a.position,
      })),
    }));

    const resultPages: ResultPageData[] = quiz.resultPages.map((r) => ({
      id: r.id,
      title: r.title,
      description: r.description ?? null,
      position: r.position,
    }));

    return {
      quiz: {
        id: quiz.id,
        title: quiz.title,
        description: quiz.description ?? "",
        slug: quiz.slug,
        status: quiz.status,
        type: quiz.type,
      },
      questions,
      designSettings,
      quizSettings,
      resultPages,
    } as LoaderData;
  } catch (error) {
    if (error instanceof Response) throw error;
    throw data({ error: "Failed to load quiz" }, { status: 500 });
  }
};

// =============================================================================
// HEADERS (App Bridge CSP)
// =============================================================================

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

// =============================================================================
// HYDRATE FALLBACK (SSR skeleton)
// =============================================================================

export function HydrateFallback() {
  return (
    <SkeletonPage primaryAction>
      <SkeletonBodyText lines={3} />
    </SkeletonPage>
  );
}

// =============================================================================
// QUESTION TYPE RENDERERS
// =============================================================================

interface QuestionRendererProps {
  question: Question;
  selectedAnswers: string[];
  onSelectAnswer: (answerId: string, isMulti: boolean) => void;
  onTextChange: (value: string) => void;
  textValue: string;
  primaryColor: string;
  borderRadius: string;
  consentText: string;
}

function MultipleChoiceRenderer({
  question,
  selectedAnswers,
  onSelectAnswer,
  primaryColor,
  borderRadius,
}: QuestionRendererProps) {
  const isMulti = question.settings.allowMultiple === true;

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
      {question.answers.length === 0 ? (
        <div
          style={{
            padding: "16px",
            textAlign: "center",
            color: "#6d7175",
            border: "1px dashed #c9cccf",
            borderRadius: `${borderRadius}px`,
          }}
        >
          No answer options added yet
        </div>
      ) : (
        question.answers.map((answer) => {
          const isSelected = selectedAnswers.includes(answer.id);
          return (
            <button
              key={answer.id}
              type="button"
              onClick={() => onSelectAnswer(answer.id, isMulti)}
              style={{
                display: "block",
                width: "100%",
                padding: "14px 18px",
                textAlign: "left",
                cursor: "pointer",
                border: isSelected
                  ? `2px solid ${primaryColor}`
                  : "2px solid #e1e3e5",
                borderRadius: `${borderRadius}px`,
                background: isSelected
                  ? `${primaryColor}14`
                  : "#ffffff",
                color: "#202223",
                fontSize: "15px",
                fontWeight: isSelected ? 600 : 400,
                transition: "all 0.15s ease",
                outline: "none",
              }}
            >
              {answer.text || "(empty option)"}
            </button>
          );
        })
      )}
    </div>
  );
}

function ImageChoiceRenderer({
  question,
  selectedAnswers,
  onSelectAnswer,
  primaryColor,
  borderRadius,
}: QuestionRendererProps) {
  return (
    <div
      style={{
        display: "grid",
        gridTemplateColumns: "repeat(auto-fill, minmax(130px, 1fr))",
        gap: "12px",
      }}
    >
      {question.answers.length === 0 ? (
        <div
          style={{
            gridColumn: "1 / -1",
            padding: "16px",
            textAlign: "center",
            color: "#6d7175",
            border: "1px dashed #c9cccf",
            borderRadius: `${borderRadius}px`,
          }}
        >
          No image options added yet
        </div>
      ) : (
        question.answers.map((answer) => {
          const isSelected = selectedAnswers.includes(answer.id);
          return (
            <button
              key={answer.id}
              type="button"
              onClick={() => onSelectAnswer(answer.id, false)}
              style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                gap: "8px",
                padding: "12px",
                cursor: "pointer",
                border: isSelected
                  ? `2px solid ${primaryColor}`
                  : "2px solid #e1e3e5",
                borderRadius: `${borderRadius}px`,
                background: isSelected ? `${primaryColor}14` : "#ffffff",
                color: "#202223",
                fontSize: "13px",
                fontWeight: isSelected ? 600 : 400,
                transition: "all 0.15s ease",
                outline: "none",
              }}
            >
              <div
                style={{
                  width: "80px",
                  height: "80px",
                  borderRadius: `${borderRadius}px`,
                  background: "#f1f2f3",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  color: "#8c9196",
                  fontSize: "11px",
                  overflow: "hidden",
                }}
              >
                {answer.imageUrl ? (
                  <img
                    src={answer.imageUrl}
                    alt={answer.text}
                    style={{ width: "100%", height: "100%", objectFit: "cover" }}
                  />
                ) : (
                  "Image"
                )}
              </div>
              <span>{answer.text || "(no label)"}</span>
            </button>
          );
        })
      )}
    </div>
  );
}

function DropdownRenderer({
  question,
  selectedAnswers,
  onSelectAnswer,
  borderRadius,
}: QuestionRendererProps) {
  const currentValue = selectedAnswers[0] ?? "";
  return (
    <select
      value={currentValue}
      onChange={(e) => onSelectAnswer(e.target.value, false)}
      style={{
        width: "100%",
        padding: "12px 16px",
        fontSize: "15px",
        border: "2px solid #e1e3e5",
        borderRadius: `${borderRadius}px`,
        background: "#ffffff",
        color: "#202223",
        cursor: "pointer",
        outline: "none",
        appearance: "auto",
      }}
    >
      <option value="">Select an option...</option>
      {question.answers.map((answer) => (
        <option key={answer.id} value={answer.id}>
          {answer.text || "(empty option)"}
        </option>
      ))}
    </select>
  );
}

function SliderRenderer({
  question,
  onTextChange,
  textValue,
  primaryColor,
  borderRadius,
}: QuestionRendererProps) {
  const min = question.settings.min ?? 0;
  const max = question.settings.max ?? 100;
  const step = question.settings.step ?? 1;
  const unit = question.settings.unit ?? "";
  const minLabel = question.settings.minLabel ?? String(min);
  const maxLabel = question.settings.maxLabel ?? String(max);
  const currentValue = textValue !== "" ? Number(textValue) : Math.round((min + max) / 2);

  return (
    <div style={{ padding: "8px 0" }}>
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={currentValue}
        onChange={(e) => onTextChange(e.target.value)}
        style={{
          width: "100%",
          accentColor: primaryColor,
          cursor: "pointer",
          borderRadius: `${borderRadius}px`,
        }}
      />
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          marginTop: "8px",
          fontSize: "13px",
          color: "#6d7175",
        }}
      >
        <span>{minLabel}</span>
        <span style={{ fontWeight: 600, color: primaryColor }}>
          {currentValue}
          {unit ? ` ${unit}` : ""}
        </span>
        <span>{maxLabel}</span>
      </div>
    </div>
  );
}

function TextInputRenderer({
  question,
  onTextChange,
  textValue,
  borderRadius,
}: QuestionRendererProps) {
  const placeholder = question.settings.placeholder ?? "Type your answer here...";
  const maxLength = question.settings.maxLength;

  return (
    <div>
      <textarea
        value={textValue}
        onChange={(e) => onTextChange(e.target.value)}
        placeholder={placeholder}
        maxLength={maxLength}
        rows={4}
        style={{
          width: "100%",
          padding: "12px 16px",
          fontSize: "15px",
          border: "2px solid #e1e3e5",
          borderRadius: `${borderRadius}px`,
          background: "#ffffff",
          color: "#202223",
          resize: "vertical",
          outline: "none",
          boxSizing: "border-box",
          fontFamily: "inherit",
        }}
      />
      {maxLength && (
        <div style={{ textAlign: "right", fontSize: "12px", color: "#8c9196", marginTop: "4px" }}>
          {textValue.length} / {maxLength}
        </div>
      )}
    </div>
  );
}

function EmailRenderer({
  question,
  onTextChange,
  textValue,
  primaryColor,
  borderRadius,
}: QuestionRendererProps) {
  const consentText =
    question.settings.consentText ?? "I agree to receive marketing emails.";
  const skipLinkText = question.settings.skipLinkText ?? "Skip";

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "14px" }}>
      <input
        type="email"
        value={textValue}
        onChange={(e) => onTextChange(e.target.value)}
        placeholder="your@email.com"
        style={{
          width: "100%",
          padding: "12px 16px",
          fontSize: "15px",
          border: "2px solid #e1e3e5",
          borderRadius: `${borderRadius}px`,
          background: "#ffffff",
          color: "#202223",
          outline: "none",
          boxSizing: "border-box",
        }}
      />
      <label
        style={{
          display: "flex",
          alignItems: "flex-start",
          gap: "10px",
          cursor: "pointer",
          fontSize: "13px",
          color: "#6d7175",
        }}
      >
        <input
          type="checkbox"
          style={{ marginTop: "2px", accentColor: primaryColor }}
        />
        <span>{consentText}</span>
      </label>
      {skipLinkText && (
        <button
          type="button"
          style={{
            background: "none",
            border: "none",
            color: "#6d7175",
            fontSize: "13px",
            cursor: "pointer",
            textDecoration: "underline",
            padding: 0,
            textAlign: "left",
          }}
        >
          {skipLinkText}
        </button>
      )}
    </div>
  );
}

function RatingRenderer({
  question,
  onTextChange,
  textValue,
  primaryColor,
}: QuestionRendererProps) {
  const maxRating = question.settings.maxRating ?? 5;
  const ratingStyle = question.settings.ratingStyle ?? "stars";
  const currentRating = textValue !== "" ? Number(textValue) : 0;

  const items = Array.from({ length: maxRating }, (_, i) => i + 1);

  if (ratingStyle === "stars") {
    return (
      <div style={{ display: "flex", gap: "8px" }}>
        {items.map((star) => (
          <button
            key={star}
            type="button"
            onClick={() => onTextChange(String(star))}
            style={{
              background: "none",
              border: "none",
              cursor: "pointer",
              fontSize: "32px",
              color: star <= currentRating ? primaryColor : "#c9cccf",
              padding: "2px",
              outline: "none",
              transition: "color 0.1s ease",
            }}
          >
            ★
          </button>
        ))}
      </div>
    );
  }

  return (
    <div style={{ display: "flex", gap: "8px", flexWrap: "wrap" }}>
      {items.map((num) => (
        <button
          key={num}
          type="button"
          onClick={() => onTextChange(String(num))}
          style={{
            width: "44px",
            height: "44px",
            border: num === currentRating ? `2px solid ${primaryColor}` : "2px solid #e1e3e5",
            borderRadius: "8px",
            background: num === currentRating ? `${primaryColor}14` : "#ffffff",
            color: num === currentRating ? primaryColor : "#202223",
            fontSize: "16px",
            fontWeight: num === currentRating ? 700 : 400,
            cursor: "pointer",
            outline: "none",
            transition: "all 0.1s ease",
          }}
        >
          {num}
        </button>
      ))}
    </div>
  );
}

function QuestionTypeRenderer(props: QuestionRendererProps) {
  switch (props.question.type) {
    case "multiple-choice":
      return <MultipleChoiceRenderer {...props} />;
    case "image-choice":
      return <ImageChoiceRenderer {...props} />;
    case "dropdown":
      return <DropdownRenderer {...props} />;
    case "slider":
      return <SliderRenderer {...props} />;
    case "text-input":
      return <TextInputRenderer {...props} />;
    case "email":
      return <EmailRenderer {...props} />;
    case "rating":
      return <RatingRenderer {...props} />;
    default:
      return (
        <div style={{ color: "#6d7175", fontSize: "14px", fontStyle: "italic" }}>
          Unsupported question type: {props.question.type}
        </div>
      );
  }
}

// =============================================================================
// PROGRESS BAR
// =============================================================================

interface ProgressBarProps {
  current: number;
  total: number;
  style: string;
  primaryColor: string;
}

function ProgressBar({ current, total, style, primaryColor }: ProgressBarProps) {
  const pct = total > 0 ? Math.round((current / total) * 100) : 0;

  if (style === "percentage") {
    return (
      <div style={{ textAlign: "center", fontSize: "13px", color: "#6d7175", marginBottom: "16px" }}>
        {pct}% complete
      </div>
    );
  }

  if (style === "steps") {
    return (
      <div style={{ display: "flex", gap: "6px", marginBottom: "16px" }}>
        {Array.from({ length: total }, (_, i) => (
          <div
            key={i}
            style={{
              flex: 1,
              height: "6px",
              borderRadius: "3px",
              background: i < current ? primaryColor : "#e1e3e5",
              transition: "background 0.2s ease",
            }}
          />
        ))}
      </div>
    );
  }

  // Default bar style
  return (
    <div
      style={{
        height: "6px",
        borderRadius: "3px",
        background: "#e1e3e5",
        marginBottom: "16px",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          height: "100%",
          width: `${pct}%`,
          background: primaryColor,
          borderRadius: "3px",
          transition: "width 0.3s ease",
        }}
      />
    </div>
  );
}

// =============================================================================
// QUIZ WIDGET (inline preview renderer)
// =============================================================================

interface QuizWidgetProps {
  quiz: LoaderQuiz;
  questions: Question[];
  designSettings: DesignSettings;
  quizSettings: QuizSettings;
  resultPages: ResultPageData[];
  resetKey: number;
}

function QuizWidget({
  quiz,
  questions,
  designSettings,
  quizSettings,
  resultPages,
  resetKey,
}: QuizWidgetProps) {
  const [step, setStep] = useState<PreviewStep>("welcome");
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [answers, setAnswers] = useState<Record<string, string[]>>({});
  const [textValues, setTextValues] = useState<Record<string, string>>({});

  // Reset when parent requests it via resetKey change
  const [prevResetKey, setPrevResetKey] = useState(resetKey);
  if (resetKey !== prevResetKey) {
    setPrevResetKey(resetKey);
    setStep("welcome");
    setCurrentQuestionIndex(0);
    setAnswers({});
    setTextValues({});
  }

  const {
    primaryColor,
    buttonTextColor,
    buttonText,
    fontFamily,
    borderRadius,
    showProgressBar,
    progressBarStyle,
    showQuestionCount,
    resultsHeading,
  } = designSettings;

  const { emailConsentText, showProgressBar: settingsProgressBar } = quizSettings;
  const effectiveShowProgress = showProgressBar || settingsProgressBar;

  const fontFamilyValue =
    fontFamily === "system" ? "system-ui, sans-serif" : `'${fontFamily}', system-ui, sans-serif`;

  const containerStyle: React.CSSProperties = {
    fontFamily: fontFamilyValue,
    background: "#ffffff",
    minHeight: "100%",
    borderRadius: `${borderRadius}px`,
    overflow: "hidden",
  };

  const currentQuestion = questions[currentQuestionIndex] ?? null;

  const handleSelectAnswer = useCallback(
    (questionId: string, answerId: string, isMulti: boolean) => {
      setAnswers((prev) => {
        const existing = prev[questionId] ?? [];
        if (isMulti) {
          return {
            ...prev,
            [questionId]: existing.includes(answerId)
              ? existing.filter((id) => id !== answerId)
              : [...existing, answerId],
          };
        }
        return { ...prev, [questionId]: [answerId] };
      });
    },
    [],
  );

  const handleTextChange = useCallback((questionId: string, value: string) => {
    setTextValues((prev) => ({ ...prev, [questionId]: value }));
  }, []);

  const handleNext = useCallback(() => {
    if (currentQuestionIndex < questions.length - 1) {
      setCurrentQuestionIndex((i) => i + 1);
    } else {
      setStep("results");
    }
  }, [currentQuestionIndex, questions.length]);

  const handleBack = useCallback(() => {
    if (step === "results") {
      setStep("question");
      setCurrentQuestionIndex(questions.length - 1);
    } else if (currentQuestionIndex > 0) {
      setCurrentQuestionIndex((i) => i - 1);
    } else {
      setStep("welcome");
    }
  }, [step, currentQuestionIndex, questions.length]);

  const buttonStyle: React.CSSProperties = {
    display: "inline-block",
    padding: "12px 28px",
    background: primaryColor,
    color: buttonTextColor,
    border: "none",
    borderRadius: `${borderRadius}px`,
    fontSize: "15px",
    fontWeight: 600,
    cursor: "pointer",
    fontFamily: "inherit",
    transition: "opacity 0.15s ease",
    outline: "none",
    lineHeight: 1.4,
  };

  const ghostButtonStyle: React.CSSProperties = {
    ...buttonStyle,
    background: "transparent",
    color: "#6d7175",
    border: "2px solid #e1e3e5",
  };

  // ── Welcome screen ──────────────────────────────────────────────────────────
  if (step === "welcome") {
    return (
      <div style={containerStyle}>
        <div
          style={{
            padding: "40px 32px",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            textAlign: "center",
            gap: "20px",
          }}
        >
          <div
            style={{
              width: "64px",
              height: "64px",
              borderRadius: "50%",
              background: `${primaryColor}1a`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontSize: "28px",
            }}
          >
            ✨
          </div>
          <div>
            <h2
              style={{
                margin: "0 0 10px",
                fontSize: "22px",
                fontWeight: 700,
                color: "#202223",
                lineHeight: 1.3,
              }}
            >
              {quiz.title || "Untitled Quiz"}
            </h2>
            {quiz.description && (
              <p
                style={{
                  margin: 0,
                  fontSize: "15px",
                  color: "#6d7175",
                  lineHeight: 1.6,
                }}
              >
                {quiz.description}
              </p>
            )}
          </div>
          {questions.length > 0 && (
            <p style={{ margin: 0, fontSize: "13px", color: "#8c9196" }}>
              {questions.length} question{questions.length !== 1 ? "s" : ""} · ~
              {Math.ceil(questions.length * 0.3)} min
            </p>
          )}
          <button
            type="button"
            style={{ ...buttonStyle, marginTop: "8px" }}
            onClick={() => {
              if (questions.length === 0) {
                setStep("results");
              } else {
                setCurrentQuestionIndex(0);
                setStep("question");
              }
            }}
          >
            Start Quiz
          </button>
        </div>
      </div>
    );
  }

  // ── Results screen ──────────────────────────────────────────────────────────
  if (step === "results") {
    const resultPage = resultPages[0] ?? null;
    return (
      <div style={containerStyle}>
        <div style={{ padding: "32px 24px" }}>
          <h2
            style={{
              margin: "0 0 6px",
              fontSize: "20px",
              fontWeight: 700,
              color: "#202223",
            }}
          >
            {resultsHeading}
          </h2>
          {resultPage ? (
            <p style={{ margin: "0 0 24px", fontSize: "15px", color: "#6d7175" }}>
              {resultPage.title}
            </p>
          ) : (
            <p
              style={{
                margin: "0 0 24px",
                fontSize: "14px",
                color: "#8c9196",
                fontStyle: "italic",
              }}
            >
              Based on your answers, here are your personalized recommendations.
            </p>
          )}
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(2, 1fr)",
              gap: "12px",
              marginBottom: "24px",
            }}
          >
            {[1, 2, 3, 4].map((n) => (
              <div
                key={n}
                style={{
                  border: "1px solid #e1e3e5",
                  borderRadius: `${borderRadius}px`,
                  overflow: "hidden",
                }}
              >
                <div
                  style={{
                    height: "100px",
                    background: "#f1f2f3",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    color: "#8c9196",
                    fontSize: "12px",
                  }}
                >
                  Product {n}
                </div>
                <div style={{ padding: "10px 12px" }}>
                  <div
                    style={{
                      height: "10px",
                      background: "#e1e3e5",
                      borderRadius: "4px",
                      marginBottom: "6px",
                    }}
                  />
                  <div
                    style={{
                      height: "10px",
                      background: "#e1e3e5",
                      borderRadius: "4px",
                      width: "60%",
                    }}
                  />
                </div>
              </div>
            ))}
          </div>
          <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
            <button type="button" style={buttonStyle}>
              Shop Now
            </button>
            <button type="button" style={ghostButtonStyle} onClick={handleBack}>
              Back
            </button>
          </div>
        </div>
      </div>
    );
  }

  // ── Question screen ─────────────────────────────────────────────────────────
  if (!currentQuestion) return null;

  const questionAnswers = answers[currentQuestion.id] ?? [];
  const questionTextValue = textValues[currentQuestion.id] ?? "";
  const isMulti = currentQuestion.settings.allowMultiple === true;

  const canAdvance =
    !currentQuestion.required ||
    questionAnswers.length > 0 ||
    questionTextValue.trim().length > 0;

  return (
    <div style={containerStyle}>
      <div style={{ padding: "24px" }}>
        {effectiveShowProgress && (
          <ProgressBar
            current={currentQuestionIndex + 1}
            total={questions.length}
            style={progressBarStyle}
            primaryColor={primaryColor}
          />
        )}

        {showQuestionCount && (
          <p
            style={{
              margin: "0 0 8px",
              fontSize: "12px",
              color: "#8c9196",
              fontWeight: 600,
              textTransform: "uppercase",
              letterSpacing: "0.05em",
            }}
          >
            Question {currentQuestionIndex + 1} of {questions.length}
          </p>
        )}

        <h3
          style={{
            margin: "0 0 8px",
            fontSize: "18px",
            fontWeight: 700,
            color: "#202223",
            lineHeight: 1.4,
          }}
        >
          {currentQuestion.title || "Untitled question"}
          {currentQuestion.required && (
            <span style={{ color: primaryColor, marginLeft: "4px" }}>*</span>
          )}
        </h3>

        {currentQuestion.description && (
          <p
            style={{
              margin: "0 0 20px",
              fontSize: "14px",
              color: "#6d7175",
              lineHeight: 1.6,
            }}
          >
            {currentQuestion.description}
          </p>
        )}

        {!currentQuestion.description && <div style={{ marginBottom: "20px" }} />}

        <QuestionTypeRenderer
          question={currentQuestion}
          selectedAnswers={questionAnswers}
          onSelectAnswer={(answerId, multi) =>
            handleSelectAnswer(currentQuestion.id, answerId, multi)
          }
          onTextChange={(value) => handleTextChange(currentQuestion.id, value)}
          textValue={questionTextValue}
          primaryColor={primaryColor}
          borderRadius={borderRadius}
          consentText={emailConsentText}
        />

        {isMulti && questionAnswers.length > 0 && (
          <p
            style={{
              marginTop: "8px",
              fontSize: "12px",
              color: "#6d7175",
              fontStyle: "italic",
            }}
          >
            {questionAnswers.length} selected
          </p>
        )}

        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            marginTop: "28px",
            gap: "12px",
          }}
        >
          <button
            type="button"
            style={ghostButtonStyle}
            onClick={handleBack}
          >
            Back
          </button>
          <button
            type="button"
            style={{
              ...buttonStyle,
              opacity: canAdvance ? 1 : 0.5,
              cursor: canAdvance ? "pointer" : "not-allowed",
            }}
            onClick={canAdvance ? handleNext : undefined}
            disabled={!canAdvance}
          >
            {currentQuestionIndex === questions.length - 1
              ? "See Results"
              : buttonText || "Next"}
          </button>
        </div>
      </div>
    </div>
  );
}

// =============================================================================
// MAIN PAGE COMPONENT
