export default function QuizPreviewPage() {
  const { quiz, questions, designSettings, quizSettings, resultPages } =
    useLoaderData<typeof loader>();

  const [deviceMode, setDeviceMode] = useState<DeviceMode>("desktop");
  const [resetKey, setResetKey] = useState(0);

  const handleReset = useCallback(() => {
    setResetKey((k) => k + 1);
  }, []);

  const isMobile = deviceMode === "mobile";

  const statusTone =
    quiz.status === "active"
      ? "success"
      : quiz.status === "paused"
        ? "warning"
        : quiz.status === "archived"
          ? "critical"
          : "info";

  const containerWidth = isMobile ? 375 : 800;

  return (
    <Page
      backAction={{ content: "Quiz Editor", url: `/app/quizzes/${quiz.id}` }}
      title={`Preview: ${quiz.title}`}
      titleMetadata={
        <Badge tone={statusTone}>
          {quiz.status.charAt(0).toUpperCase() + quiz.status.slice(1)}
        </Badge>
      }
    >
      <BlockStack gap="400">
        {/* Device toggle + controls */}
        <Card>
          <Box padding="300">
            <InlineStack align="space-between" blockAlign="center">
              <InlineStack gap="200" blockAlign="center">
                <Text as="span" variant="bodyMd" tone="subdued">
                  Preview mode:
                </Text>
                <ButtonGroup variant="segmented">
                  <Button
                    pressed={deviceMode === "desktop"}
                    icon={DesktopIcon}
                    onClick={() => setDeviceMode("desktop")}
                    size="slim"
                  >
                    Desktop
                  </Button>
                  <Button
                    pressed={deviceMode === "mobile"}
                    icon={MobileIcon}
                    onClick={() => setDeviceMode("mobile")}
                    size="slim"
                  >
                    Mobile
                  </Button>
                </ButtonGroup>
              </InlineStack>
              <InlineStack gap="200" blockAlign="center">
                <Text as="span" variant="bodySm" tone="subdued">
                  {questions.length} question{questions.length !== 1 ? "s" : ""}
                </Text>
                <Divider />
                <Button
                  icon={RefreshIcon}
                  size="slim"
                  onClick={handleReset}
                  accessibilityLabel="Restart quiz preview"
                >
                  Restart
                </Button>
              </InlineStack>
            </InlineStack>
          </Box>
        </Card>

        {/* Preview area */}
        <div
          style={{
            display: "flex",
            justifyContent: "center",
            alignItems: "flex-start",
            padding: "24px 0",
            minHeight: "500px",
            background: "#f1f2f3",
            borderRadius: "8px",
          }}
        >
          {/* Phone frame for mobile */}
          {isMobile ? (
            <div
              style={{
                position: "relative",
                width: containerWidth + 32,
                borderRadius: "36px",
                background: "#1c1c1e",
                padding: "16px",
                boxShadow:
                  "0 0 0 2px #3a3a3c, 0 20px 60px rgba(0,0,0,0.4)",
              }}
            >
              {/* Phone notch */}
              <div
                style={{
                  position: "absolute",
                  top: "16px",
                  left: "50%",
                  transform: "translateX(-50%)",
                  width: "80px",
                  height: "6px",
                  background: "#3a3a3c",
                  borderRadius: "3px",
                  zIndex: 1,
                }}
              />
              <div
                style={{
                  width: containerWidth,
                  background: "#ffffff",
                  borderRadius: "24px",
                  minHeight: "560px",
                  overflow: "hidden",
                  marginTop: "20px",
                }}
              >
                <QuizWidget
                  key={resetKey}
                  quiz={quiz}
                  questions={questions}
                  designSettings={designSettings}
                  quizSettings={quizSettings}
                  resultPages={resultPages}
                  resetKey={resetKey}
                />
              </div>
            </div>
          ) : (
            <div
              style={{
                width: "100%",
                maxWidth: containerWidth,
                background: "#ffffff",
                borderRadius: "8px",
                boxShadow: "0 2px 8px rgba(0,0,0,0.12)",
                minHeight: "500px",
                overflow: "hidden",
              }}
            >
              <QuizWidget
                key={resetKey}
                quiz={quiz}
                questions={questions}
                designSettings={designSettings}
                quizSettings={quizSettings}
                resultPages={resultPages}
                resetKey={resetKey}
              />
            </div>
          )}
        </div>

        {/* Info callout */}
        <Card>
          <Box padding="300">
            <BlockStack gap="100">
              <Text as="p" variant="bodySm" tone="subdued">
                This is a live preview of how your quiz appears to shoppers.
                Navigation, answer selection, and question flow work as in the
                real storefront experience. Product recommendations on the
                results screen are shown as placeholders.
              </Text>
            </BlockStack>
          </Box>
        </Card>
      </BlockStack>
    </Page>
  );
}

